import { resolveAgentV2Hosting as resolveAgentV2HostingInternal } from "./internal/v2-hosting.js";
/**
 * Reports how this process is hosted. The store-id resolver stays inside
 * the package. Callers branch on `kind`.
 */
export function resolveAgentV2Hosting(input) {
    return { kind: resolveAgentV2HostingInternal(input).kind };
}
